-- Rule exercises: short questions on a grammar rule (fill the gap, or pick one option), generated by the LLM so each set
-- brings new sentences. The answers are kept to pick what to ask next and for the per-rule numbers on the page.
CREATE TABLE rule_exercises (
  id                INTEGER PRIMARY KEY,
  rule_id           INTEGER NOT NULL REFERENCES rules(id) ON DELETE CASCADE,
  kind              TEXT NOT NULL CHECK (kind IN ('gap', 'choice')),
  question          TEXT NOT NULL,              -- the task in Ukrainian: «Встав прикметник у правильній формі»
  sentence          TEXT NOT NULL,              -- Dutch, ___ marks the gap; '' for a choice between whole sentences
  hint              TEXT,                       -- shown in brackets after the gap, e.g. the base form «groot»
  translation       TEXT,                       -- Ukrainian translation of the full sentence
  answer            TEXT NOT NULL,
  accepted_answers  TEXT NOT NULL DEFAULT '[]', -- JSON array: other right answers for a gap
  options           TEXT,                       -- JSON array for a choice, the answer among them
  explanation       TEXT NOT NULL,              -- Ukrainian, why this answer, with the rule code
  sentence_key      TEXT NOT NULL UNIQUE,       -- lowercased sentence + answer, so a repeat is not saved twice
  source            TEXT NOT NULL DEFAULT 'openrouter',
  created_at        INTEGER NOT NULL
);
CREATE INDEX index_rule_exercises_on_rule_id ON rule_exercises(rule_id);

CREATE TABLE rule_exercise_answers (
  id           INTEGER PRIMARY KEY,
  exercise_id  INTEGER NOT NULL REFERENCES rule_exercises(id) ON DELETE CASCADE,
  answer       TEXT NOT NULL,
  is_correct   INTEGER NOT NULL CHECK (is_correct IN (0, 1)),
  answered_at  INTEGER NOT NULL
);
CREATE INDEX index_rule_exercise_answers_on_exercise_id ON rule_exercise_answers(exercise_id);
